// quiz_diff.js — Quizfragen zur Differentialrechnung (wird von 116_quiz.js bei Bedarf geladen)
// Je Ansicht 30 Fragen: 12 × Stufe 1 (Grundwissen), 10 × Stufe 2 (Verständnis), 8 × Stufe 3 (Knacknuss).
// Die Reihenfolge hier ist die Reihenfolge im Quiz und auf dem Arbeitsblatt (Frage 1 bis 30).
// {l, q, a, e}: a[0] ist die richtige Antwort (Anzeige gemischt)   ·   {l, q, tf, e}: Aussage, tf = wahr/falsch
// Formeln in $…$; r`…` = String.raw, damit LaTeX ohne doppelte Rückstriche geschrieben werden kann.
(function () {
  const r = String.raw;
  (window.QUIZ_DATA = window.QUIZ_DATA || {}).diff = {

    // ───────────────────────── Grenzwerte von Funktionen ─────────────────────────
    lim: [
      { l: 1, q: r`Was bedeutet $\lim_{x\to 2} f(x)=5$?`, a: [r`Nähert sich $x$ der Stelle 2, so nähern sich die Funktionswerte der Zahl 5.`, r`Es ist $f(2)=5$.`, r`Es ist $f(5)=2$.`, r`Für $x>2$ ist $f(x)>5$.`], e: r`Der Grenzwert beschreibt, wohin die Funktionswerte streben, wenn $x$ der Stelle beliebig nahe kommt.` },
      { l: 1, q: r`Wie gross ist $\lim_{x\to 3}\,(2x+1)$?`, a: [r`$7$`, r`$6$`, r`$3$`, r`Der Grenzwert existiert nicht.`], e: r`Die Funktion ist überall stetig, man darf einsetzen: $2\cdot 3+1=7$.` },
      { l: 1, q: r`Für den Grenzwert $\lim_{x\to a}f(x)$ spielt es keine Rolle, welchen Wert $f$ an der Stelle $a$ selbst hat.`, tf: true, e: r`Es zählen nur die Werte in der Nähe von $a$. $f(a)$ muss nicht einmal definiert sein.` },
      { l: 1, q: r`Wie gross ist $\lim_{x\to\infty}\frac{1}{x}$?`, a: [r`$0$`, r`$1$`, r`$\infty$`, r`Der Grenzwert existiert nicht.`], e: r`Je grösser $x$ wird, desto näher liegt $\frac1x$ bei 0.` },
      { l: 1, q: r`Der Grenzwert $\lim_{x\to a}f(x)$ existiert genau dann, wenn …`, a: [r`der linksseitige und der rechtsseitige Grenzwert existieren und gleich sind.`, r`$f(a)$ definiert ist.`, r`$f(a)=0$ ist.`, r`der linksseitige Grenzwert existiert.`], e: r`Von beiden Seiten müssen sich die Funktionswerte derselben Zahl nähern.` },
      { l: 1, q: r`Wie gross ist $\lim_{x\to 1}\frac{x^2-1}{x-1}$?`, a: [r`$2$`, r`$0$`, r`$1$`, r`Der Grenzwert existiert nicht.`], e: r`Für $x\neq 1$ ist $\frac{(x-1)(x+1)}{x-1}=x+1$, und das geht gegen 2.` },
      { l: 1, q: r`Hat $f$ bei $a$ eine Polstelle, so ist $\lim_{x\to a}f(x)$ eine bestimmte Zahl.`, tf: false, e: r`An einer Polstelle wachsen oder fallen die Funktionswerte über alle Grenzen.` },
      { l: 1, q: r`Was geschieht mit $f(x)=\frac1x$, wenn sich $x$ von rechts ($x>0$) der Stelle 0 nähert?`, a: [r`Die Werte wachsen über alle Grenzen ($+\infty$).`, r`Die Werte gehen gegen 0.`, r`Die Werte fallen unter alle Grenzen ($-\infty$).`, r`Die Werte gehen gegen 1.`], e: r`Zum Beispiel $\frac{1}{0.1}=10$, $\frac{1}{0.001}=1000$: Der Kehrwert einer kleinen positiven Zahl ist gross.` },
      { l: 1, q: r`Wie gross ist $\lim_{x\to\infty}\frac{3x+1}{x}$?`, a: [r`$3$`, r`$0$`, r`$1$`, r`$\infty$`], e: r`$\frac{3x+1}{x}=3+\frac1x$, und $\frac1x$ geht gegen 0.` },
      { l: 1, q: r`Eine Funktion heisst an der Stelle $a$ stetig, wenn …`, a: [r`$\lim_{x\to a}f(x)=f(a)$ gilt.`, r`$f(a)$ definiert ist.`, r`$f(a)=0$ ist.`, r`der Graph bei $a$ die $x$-Achse schneidet.`], e: r`Grenzwert und Funktionswert müssen übereinstimmen: Der Graph lässt sich dort ohne Absetzen zeichnen.` },
      { l: 1, q: r`Was ist eine hebbare Lücke?`, a: [r`Eine Stelle, an der $f$ nicht definiert ist, der Grenzwert aber existiert.`, r`Eine Stelle mit senkrechter Asymptote.`, r`Eine Stelle, an der der Graph springt.`, r`Eine Nullstelle von $f$.`], e: r`Die Lücke lässt sich schliessen, indem man den Grenzwert als Funktionswert festlegt.` },
      { l: 1, q: r`$\lim_{x\to 0}\frac{1}{x^2}=\infty$ bedeutet: Die Funktionswerte werden beliebig gross, wenn $x$ gegen 0 geht.`, tf: true, e: r`«$=\infty$» ist keine Zahl, sondern eine Kurzschreibweise für unbeschränktes Wachsen.` },

      { l: 2, q: r`Gegeben ist $f(x)=\frac{|x|}{x}$. Was gilt für $x\to 0$?`, a: [r`Von links $-1$, von rechts $1$: Der Grenzwert existiert nicht.`, r`Der Grenzwert ist 0.`, r`Der Grenzwert ist 1.`, r`Von beiden Seiten wachsen die Werte über alle Grenzen.`], e: r`Für $x<0$ ist $f(x)=-1$, für $x>0$ ist $f(x)=1$. Die einseitigen Grenzwerte sind verschieden (Sprung).` },
      { l: 2, q: r`Wie gross ist $\lim_{x\to\infty}\frac{2x^2+3}{5x^2-x}$?`, a: [r`$\frac25$`, r`$0$`, r`$\infty$`, r`$\frac35$`], e: r`Zähler und Nenner durch $x^2$ teilen: $\frac{2+3/x^2}{5-1/x}\to\frac25$.` },
      { l: 2, q: r`Wie gross ist $\lim_{x\to\infty}\frac{x+1}{x^2+1}$?`, a: [r`$0$`, r`$1$`, r`$\infty$`, r`$\frac12$`], e: r`Der Nenner hat den höheren Grad und wächst schneller als der Zähler.` },
      { l: 2, q: r`Ist $f(2)=7$, so ist auch $\lim_{x\to 2}f(x)=7$.`, tf: false, e: r`Das gilt nur, wenn $f$ bei 2 stetig ist. Bei einem Sprung oder einem einzelnen «versetzten» Punkt stimmt es nicht.` },
      { l: 2, q: r`Für $x\neq 2$ ist $f(x)=\frac{x^2-4}{x-2}$. Mit welchem Wert $f(2)$ wird $f$ stetig?`, a: [r`$4$`, r`$0$`, r`$2$`, r`Mit keinem Wert.`], e: r`Für $x\neq2$ ist $f(x)=x+2$, der Grenzwert bei 2 ist also 4.` },
      { l: 2, q: r`Wie verhält sich $f(x)=\frac{1}{(x-2)^2}$ für $x\to 2$?`, a: [r`Von beiden Seiten gegen $+\infty$.`, r`Von links gegen $-\infty$, von rechts gegen $+\infty$.`, r`Gegen 0.`, r`Gegen $\frac14$.`], e: r`Das Quadrat im Nenner ist auf beiden Seiten positiv: Polstelle ohne Vorzeichenwechsel.` },
      { l: 2, q: r`$x$ nähert sich der Stelle 3 von links ($x<3$). Was geschieht mit $\frac{1}{x-3}$?`, a: [r`Die Werte fallen unter alle Grenzen ($-\infty$).`, r`Die Werte wachsen über alle Grenzen ($+\infty$).`, r`Die Werte gehen gegen 0.`, r`Die Werte gehen gegen $\frac13$.`], e: r`Für $x<3$ ist der Nenner eine kleine negative Zahl, der Bruch also stark negativ.` },
      { l: 2, q: r`Welche waagrechte Asymptote hat $f(x)=\frac{4x-1}{2x+3}$?`, a: [r`$y=2$`, r`$y=4$`, r`$y=-\frac13$`, r`$y=0$`], e: r`Für $x\to\pm\infty$ zählt nur das Verhältnis der höchsten Potenzen: $\frac{4x}{2x}=2$.` },
      { l: 2, q: r`Der Graph einer Funktion kann seine waagrechte Asymptote schneiden.`, tf: true, e: r`Die Asymptote beschreibt nur das Verhalten für $x\to\pm\infty$. Zum Beispiel schneidet $\frac{x}{x^2+1}$ die Asymptote $y=0$ bei $x=0$.` },
      { l: 2, q: r`Wie gross ist $\lim_{h\to 0}\frac{(3+h)^2-9}{h}$?`, a: [r`$6$`, r`$0$`, r`$9$`, r`Der Grenzwert existiert nicht.`], e: r`$\frac{6h+h^2}{h}=6+h$ für $h\neq0$, und das geht gegen 6.` },

      { l: 3, q: r`Wie gross ist $\lim_{x\to 0}\frac{\sin x}{x}$ ($x$ im Bogenmass)?`, a: [r`$1$`, r`$0$`, r`$\infty$`, r`Der Grenzwert existiert nicht.`], e: r`Für kleine Winkel im Bogenmass ist $\sin x\approx x$.` },
      { l: 3, q: r`Wie gross ist $\lim_{x\to\infty}\left(\sqrt{x^2+x}-x\right)$?`, a: [r`$\frac12$`, r`$0$`, r`$\infty$`, r`$1$`], e: r`Erweitern mit $\sqrt{x^2+x}+x$ ergibt $\frac{x}{\sqrt{x^2+x}+x}$, und das geht gegen $\frac12$.` },
      { l: 3, q: r`Was gilt für $\lim_{x\to 0}\sin\frac1x$?`, a: [r`Er existiert nicht: Die Werte schwanken unendlich oft zwischen $-1$ und $1$.`, r`Er ist 0.`, r`Er ist 1.`, r`Er ist $\infty$.`], e: r`In jeder noch so kleinen Umgebung von 0 nimmt $\sin\frac1x$ alle Werte von $-1$ bis $1$ an.` },
      { l: 3, q: r`Es gilt $\lim_{x\to 0}\,x\cdot\sin\frac1x=0$.`, tf: true, e: r`Wegen $\left|x\sin\frac1x\right|\le|x|$ wird der Ausdruck zwischen $-|x|$ und $|x|$ eingeklemmt.` },
      { l: 3, q: r`Wie gross ist $\lim_{x\to\infty}\left(1+\frac1x\right)^x$?`, a: [r`$e\approx 2.718$`, r`$1$`, r`$\infty$`, r`$2$`], e: r`Das ist eine der Definitionen der eulerschen Zahl. «$1^\infty$» ist kein fester Wert.` },
      { l: 3, q: r`Wie gross ist $\lim_{x\to 1}\frac{x^3-1}{x^2-1}$?`, a: [r`$\frac32$`, r`$1$`, r`$0$`, r`Der Grenzwert existiert nicht.`], e: r`$\frac{(x-1)(x^2+x+1)}{(x-1)(x+1)}=\frac{x^2+x+1}{x+1}\to\frac32$.` },
      { l: 3, q: r`Für $x<1$ ist $f(x)=x^2+a$, für $x\ge 1$ ist $f(x)=3x$. Für welches $a$ ist $f$ bei 1 stetig?`, a: [r`$a=2$`, r`$a=3$`, r`$a=1$`, r`$a=0$`], e: r`Von links ergibt sich $1+a$, von rechts 3. Beides muss gleich sein.` },
      { l: 3, q: r`Haben $f$ und $g$ an der Stelle $a$ beide keinen Grenzwert, so hat auch $f+g$ dort keinen Grenzwert.`, tf: false, e: r`Gegenbeispiel: $f(x)=\frac{|x|}{x}$ und $g(x)=-\frac{|x|}{x}$ bei 0. Die Summe ist konstant 0.` }
    ],

    // ───────────────────────── Sekante → Tangente ─────────────────────────
    tan: [
      { l: 1, q: r`Was ist eine Sekante?`, a: [r`Eine Gerade durch zwei Punkte des Graphen.`, r`Eine Gerade, die den Graphen in einem Punkt berührt.`, r`Eine Gerade senkrecht zur Tangente.`, r`Eine Gerade parallel zur $x$-Achse.`], e: r`Die Sekante «schneidet» den Graphen in zwei Punkten $P$ und $Q$.` },
      { l: 1, q: r`Welche Steigung hat die Sekante durch $P(x_0\,|\,f(x_0))$ und $Q(x_0+h\,|\,f(x_0+h))$?`, a: [r`$\frac{f(x_0+h)-f(x_0)}{h}$`, r`$\frac{f(x_0+h)+f(x_0)}{h}$`, r`$\frac{h}{f(x_0+h)-f(x_0)}$`, r`$f(x_0+h)-f(x_0)$`], e: r`Steigung = Höhenunterschied durch waagrechten Abstand: $\frac{\Delta y}{\Delta x}$ mit $\Delta x=h$.` },
      { l: 1, q: r`Wie heisst der Quotient $\frac{f(x_0+h)-f(x_0)}{h}$?`, a: [r`Differenzenquotient`, r`Differentialquotient`, r`Ableitungsfunktion`, r`Steigungswinkel`], e: r`Er ist der Quotient zweier Differenzen. Erst sein Grenzwert für $h\to0$ heisst Differentialquotient.` },
      { l: 1, q: r`$f(x)=x^2$. Welche Steigung hat die Sekante zwischen $x=1$ und $x=3$?`, a: [r`$4$`, r`$2$`, r`$8$`, r`$3$`], e: r`$\frac{f(3)-f(1)}{3-1}=\frac{9-1}{2}=4$.` },
      { l: 1, q: r`Die Sekantensteigung ist die mittlere Änderungsrate von $f$ zwischen den beiden Stellen.`, tf: true, e: r`Sie gibt an, um wie viel sich $f$ im Durchschnitt pro Einheit von $x$ ändert.` },
      { l: 1, q: r`Was geschieht mit der Sekante, wenn $Q$ auf dem Graphen zu $P$ wandert ($h\to 0$)?`, a: [r`Sie dreht sich in die Tangente in $P$.`, r`Sie wird waagrecht.`, r`Ihre Steigung geht immer gegen 0.`, r`Sie wird zur Normalen in $P$.`], e: r`Die Tangente ist die Grenzlage der Sekanten.` },
      { l: 1, q: r`Die Ableitung $f'(x_0)$ ist …`, a: [r`der Grenzwert des Differenzenquotienten für $h\to 0$.`, r`der Differenzenquotient für $h=1$.`, r`der Quotient $\frac{f(x_0)}{x_0}$.`, r`der Funktionswert an der Stelle $x_0$.`], e: r`$f'(x_0)=\lim_{h\to0}\frac{f(x_0+h)-f(x_0)}{h}$.` },
      { l: 1, q: r`$f(x)=x^2$. Wie gross ist $f'(3)$?`, a: [r`$6$`, r`$9$`, r`$3$`, r`$5$`], e: r`$\frac{(3+h)^2-9}{h}=6+h\to 6$.` },
      { l: 1, q: r`Was gibt $f'(x_0)$ anschaulich an?`, a: [r`Die Steigung der Tangente an den Graphen bei $x_0$.`, r`Die Höhe des Graphen bei $x_0$.`, r`Die Fläche unter dem Graphen bis $x_0$.`, r`Den $y$-Achsenabschnitt der Tangente.`], e: r`Die Ableitung ist die Steigung des Graphen an dieser Stelle.` },
      { l: 1, q: r`Für $h=0$ lässt sich der Differenzenquotient direkt ausrechnen.`, tf: false, e: r`Für $h=0$ stünde $\frac00$ da. Deshalb betrachtet man den Grenzwert für $h\to0$.` },
      { l: 1, q: r`$f(x)=2x+1$. Wie gross ist die Sekantensteigung zwischen zwei beliebigen Stellen?`, a: [r`Immer 2.`, r`Sie hängt von $h$ ab.`, r`Immer 1.`, r`Immer 0.`], e: r`Bei einer Geraden hat jede Sekante die Steigung der Geraden selbst.` },
      { l: 1, q: r`$s(t)$ ist der zurückgelegte Weg zur Zeit $t$. Was bedeutet $s'(t_0)$?`, a: [r`Die Momentangeschwindigkeit zur Zeit $t_0$.`, r`Die Durchschnittsgeschwindigkeit bis $t_0$.`, r`Den bis $t_0$ zurückgelegten Weg.`, r`Die Beschleunigung zur Zeit $t_0$.`], e: r`Die momentane Änderungsrate des Weges ist die Geschwindigkeit in diesem Augenblick.` },

      { l: 2, q: r`$f(x)=x^2$, $x_0=1$. Wie lautet der vereinfachte Differenzenquotient?`, a: [r`$2+h$`, r`$2h$`, r`$1+h$`, r`$2+h^2$`], e: r`$\frac{(1+h)^2-1}{h}=\frac{2h+h^2}{h}=2+h$.` },
      { l: 2, q: r`$f(x)=x^2$, $x_0=1$. Welche Steigung hat die Sekante für $h=0.1$?`, a: [r`$2.1$`, r`$2$`, r`$2.01$`, r`$1.9$`], e: r`$2+h=2.1$. Die Tangentensteigung 2 wird erst im Grenzwert erreicht.` },
      { l: 2, q: r`Für $h<0$ liegt $Q$ links von $P$. Welche Sekantensteigung hat $f(x)=x^2$ bei $x_0=1$ für $h=-0.1$?`, a: [r`$1.9$`, r`$2.1$`, r`$2$`, r`$-2.1$`], e: r`$2+h=2-0.1=1.9$. Von links nähert man sich der Tangentensteigung von unten.` },
      { l: 2, q: r`Der Graph beschreibt zwischen $P$ und $Q$ eine Linkskurve, und $Q$ liegt rechts von $P$ ($h>0$). Dann ist die Sekantensteigung grösser als die Tangentensteigung in $P$.`, tf: true, e: r`In einer Linkskurve nimmt die Steigung zu: Zwischen $P$ und $Q$ ist sie überall grösser als in $P$, und die Sekantensteigung ist der Mittelwert dieser Steigungen. Beispiel $f(x)=x^2$: $2x_0+h>2x_0$.` },
      { l: 2, q: r`Im Differenzenquotienten klammert man $h$ aus und kürzt: $\frac{2h+h^2}{h}=\frac{h\,(2+h)}{h}=2+h$. Warum ist das erlaubt, obwohl $h$ danach gegen 0 geht?`, a: [r`Für den Grenzwert werden nur Werte $h\neq0$ betrachtet, und durch eine Zahl ungleich null darf man teilen.`, r`Weil $h$ am Schluss ohnehin null ist.`, r`Weil $h^2$ gegenüber $2h$ vernachlässigbar ist.`, r`Es ist nur näherungsweise erlaubt.`], e: r`$h\to0$ heisst: $h$ kommt der Null beliebig nahe, ist aber nie null. Für jedes solche $h$ stimmt die Umformung exakt.` },
      { l: 2, q: r`$f(x)=x^3$. Was ergibt $\frac{(x_0+h)^3-x_0^3}{h}$ vereinfacht?`, a: [r`$3x_0^2+3x_0h+h^2$`, r`$3x_0^2+h^2$`, r`$3x_0^2h+3x_0h^2+h^3$`, r`$x_0^2+x_0h+h^2$`], e: r`$(x_0+h)^3=x_0^3+3x_0^2h+3x_0h^2+h^3$; $x_0^3$ fällt weg, dann durch $h$ teilen.` },
      { l: 2, q: r`$f(x)=|x|$ an der Stelle $x_0=0$. Was gilt?`, a: [r`Von rechts ist die Sekantensteigung 1, von links $-1$: $f'(0)$ existiert nicht.`, r`$f'(0)=0$`, r`$f'(0)=1$`, r`$f'(0)=-1$`], e: r`Der Graph hat bei 0 einen Knick. Es gibt dort keine eindeutige Tangente.` },
      { l: 2, q: r`Ein Stein fällt nach $s(t)=5t^2$ ($s$ in m, $t$ in s). Wie gross ist die Durchschnittsgeschwindigkeit zwischen $t=1$ und $t=3$?`, a: [r`$20$ m/s`, r`$10$ m/s`, r`$40$ m/s`, r`$30$ m/s`], e: r`$\frac{s(3)-s(1)}{3-1}=\frac{45-5}{2}=20$.` },
      { l: 2, q: r`Bei $s(t)=5t^2$ ist die Durchschnittsgeschwindigkeit zwischen $t=1$ und $t=3$ gleich der Momentangeschwindigkeit bei $t=2$.`, tf: true, e: r`Beide sind 20 m/s. Bei einer Parabel stimmt die Sekantensteigung immer mit der Tangentensteigung in der Mitte des Intervalls überein.` },
      { l: 2, q: r`Wie lautet die Tangente an $f(x)=x^2$ im Punkt $P(1\,|\,1)$?`, a: [r`$y=2x-1$`, r`$y=2x+1$`, r`$y=x$`, r`$y=2x$`], e: r`Steigung $f'(1)=2$; durch $P$: $1=2\cdot1+q$, also $q=-1$.` },

      { l: 3, q: r`$f(x)=\frac1x$. Was ergibt der Differenzenquotient an der Stelle $x_0$ vereinfacht?`, a: [r`$-\frac{1}{x_0(x_0+h)}$`, r`$\frac{1}{x_0(x_0+h)}$`, r`$-\frac{1}{x_0^2+h}$`, r`$-\frac{h}{x_0(x_0+h)}$`], e: r`$\frac{1}{x_0+h}-\frac{1}{x_0}=\frac{-h}{x_0(x_0+h)}$; geteilt durch $h$ bleibt $-\frac{1}{x_0(x_0+h)}$, für $h\to0$ also $-\frac{1}{x_0^2}$.` },
      { l: 3, q: r`Welche Ableitung von $f(x)=\sqrt{x}$ erhält man mit dem Differenzenquotienten (Erweitern mit $\sqrt{x_0+h}+\sqrt{x_0}$)?`, a: [r`$\frac{1}{2\sqrt{x_0}}$`, r`$\frac{1}{\sqrt{x_0}}$`, r`$2\sqrt{x_0}$`, r`$\frac{\sqrt{x_0}}{2}$`], e: r`Nach dem Erweitern steht $\frac{1}{\sqrt{x_0+h}+\sqrt{x_0}}$ da, für $h\to0$ also $\frac{1}{2\sqrt{x_0}}$.` },
      { l: 3, q: r`$f(x)=x^2$. Was ergibt der symmetrische Differenzenquotient $\frac{f(x_0+h)-f(x_0-h)}{2h}$?`, a: [r`Genau $2x_0$, für jedes $h\neq0$.`, r`$2x_0+h$`, r`$2x_0+h^2$`, r`$2x_0-h$`], e: r`$(x_0+h)^2-(x_0-h)^2=4x_0h$. Bei Parabeln trifft die symmetrische Sekante die Tangentensteigung exakt.` },
      { l: 3, q: r`Ist $f$ an der Stelle $x_0$ stetig, so existiert dort auch $f'(x_0)$.`, tf: false, e: r`Gegenbeispiel: $f(x)=|x|$ ist bei 0 stetig, hat dort aber einen Knick.` },
      { l: 3, q: r`Ist $f$ an der Stelle $x_0$ differenzierbar, so ist $f$ dort auch stetig.`, tf: true, e: r`Damit $\frac{f(x_0+h)-f(x_0)}{h}$ einen Grenzwert hat, muss der Zähler gegen 0 gehen.` },
      { l: 3, q: r`$f(x)=x^2$. An welcher Stelle ist die Tangente parallel zur Sekante durch die Punkte bei $x=a$ und $x=b$?`, a: [r`Bei $\frac{a+b}{2}$`, r`Bei $\sqrt{ab}$`, r`Bei $a$`, r`Bei $b-a$`], e: r`Sekantensteigung: $\frac{b^2-a^2}{b-a}=a+b$. Aus $2x=a+b$ folgt $x=\frac{a+b}{2}$.` },
      { l: 3, q: r`Was gilt für $f(x)=\sqrt[3]{x}$ an der Stelle 0?`, a: [r`Die Sekantensteigungen wachsen über alle Grenzen: senkrechte Tangente, $f'(0)$ existiert nicht.`, r`$f'(0)=0$`, r`$f'(0)=\frac13$`, r`Der Graph hat bei 0 einen Knick.`], e: r`$\frac{\sqrt[3]{h}}{h}=\frac{1}{\sqrt[3]{h^2}}\to\infty$ für $h\to0$.` },
      { l: 3, q: r`Wie gross ist $\lim_{h\to 0}\frac{(2+h)^5-32}{h}$?`, a: [r`$80$`, r`$32$`, r`$16$`, r`$160$`], e: r`Das ist die Ableitung von $x^5$ an der Stelle 2: $5\cdot2^4=80$.` }
    ],

    // ───────────────────────── Graphisches Ableiten ─────────────────────────
    gr: [
      { l: 1, q: r`Die Höhe des Punktes auf dem Graphen von $f'$ an der Stelle $x_0$ entspricht …`, a: [r`der Steigung der Tangente an $f$ bei $x_0$.`, r`dem Funktionswert $f(x_0)$.`, r`der Krümmung von $f$ bei $x_0$.`, r`der Stelle $x_0$ selbst.`], e: r`$f'$ ordnet jeder Stelle die Steigung von $f$ zu.` },
      { l: 1, q: r`In einem Intervall fällt der Graph von $f$. Was gilt dort für $f'$?`, a: [r`$f'(x)$ ist negativ (höchstens an einzelnen Stellen null).`, r`$f'(x)$ ist positiv.`, r`$f'$ fällt ebenfalls.`, r`$f'(x)$ ist überall null.`], e: r`Fallender Graph heisst negative Steigung: Der Graph von $f'$ liegt unter der $x$-Achse.` },
      { l: 1, q: r`An einem Hochpunkt von $f$ hat $f'$ …`, a: [r`eine Nullstelle mit Vorzeichenwechsel von plus nach minus.`, r`ebenfalls einen Hochpunkt.`, r`eine Nullstelle mit Vorzeichenwechsel von minus nach plus.`, r`eine Polstelle.`], e: r`Vor dem Hochpunkt steigt $f$ ($f'>0$), danach fällt $f$ ($f'<0$).` },
      { l: 1, q: r`An einem Tiefpunkt von $f$ wechselt $f'$ das Vorzeichen von minus nach plus.`, tf: true, e: r`Vor dem Tiefpunkt fällt $f$, danach steigt $f$.` },
      { l: 1, q: r`An einem Wendepunkt von $f$ hat $f'$ …`, a: [r`einen Hoch- oder Tiefpunkt.`, r`immer eine Nullstelle.`, r`eine Sprungstelle.`, r`immer einen Wendepunkt.`], e: r`Am Wendepunkt ist die Steigung von $f$ lokal am grössten oder am kleinsten.` },
      { l: 1, q: r`$f$ ist eine Gerade mit der Steigung 3. Wie sieht der Graph von $f'$ aus?`, a: [r`Eine waagrechte Gerade auf der Höhe 3.`, r`Eine Gerade mit der Steigung 3.`, r`Die $x$-Achse.`, r`Eine Parabel.`], e: r`Die Steigung ist überall gleich, also ist $f'(x)=3$.` },
      { l: 1, q: r`Der Graph von $f$ ist eine Parabel. Wie sieht der Graph von $f'$ aus?`, a: [r`Eine schräge Gerade.`, r`Eine Parabel.`, r`Eine waagrechte Gerade.`, r`Eine Kurve dritten Grades.`], e: r`Beim Ableiten sinkt der Grad um 1: aus $ax^2+bx+c$ wird $2ax+b$.` },
      { l: 1, q: r`Ist $f$ konstant, so ist der Graph von $f'$ die $x$-Achse.`, tf: true, e: r`Ein waagrechter Graph hat überall die Steigung 0.` },
      { l: 1, q: r`Wo ist die Steigung von $f$ am grössten?`, a: [r`Dort, wo $f'$ seinen höchsten Punkt hat.`, r`Dort, wo $f$ seinen höchsten Punkt hat.`, r`Dort, wo $f'$ eine Nullstelle hat.`, r`Dort, wo $f$ die $x$-Achse schneidet.`], e: r`Die Werte von $f'$ sind die Steigungen von $f$.` },
      { l: 1, q: r`Was bedeutet $f'(2)=0$?`, a: [r`Die Tangente an $f$ bei $x=2$ ist waagrecht.`, r`Es ist $f(2)=0$.`, r`$f$ hat bei $x=2$ eine Nullstelle.`, r`$f$ ist bei $x=2$ nicht definiert.`], e: r`Steigung 0 heisst waagrechte Tangente. Über den Funktionswert sagt das nichts.` },
      { l: 1, q: r`Verschiebt man den Graphen von $f$ nach oben, so ändert sich der Graph von $f'$ nicht.`, tf: true, e: r`Die Steigungen bleiben beim Verschieben in $y$-Richtung gleich; die Konstante fällt beim Ableiten weg.` },
      { l: 1, q: r`$f$ ist ein Polynom dritten Grades. Welchen Grad hat $f'$?`, a: [r`2`, r`3`, r`4`, r`1`], e: r`Ableiten senkt den Grad um 1.` },

      { l: 2, q: r`Der Graph von $f'$ ist eine Gerade, die bei $x=1$ von unten nach oben durch die $x$-Achse geht. Was hat $f$ bei $x=1$?`, a: [r`Einen Tiefpunkt.`, r`Einen Hochpunkt.`, r`Einen Wendepunkt.`, r`Eine Nullstelle.`], e: r`$f'$ wechselt von minus nach plus: $f$ fällt zuerst und steigt danach.` },
      { l: 2, q: r`Der Graph von $f'$ berührt die $x$-Achse bei $x=2$, ohne sie zu überqueren. Was hat $f$ bei $x=2$?`, a: [r`Einen Terrassenpunkt (Sattelpunkt).`, r`Einen Hochpunkt.`, r`Einen Tiefpunkt.`, r`Einen Knick.`], e: r`Waagrechte Tangente, aber kein Vorzeichenwechsel von $f'$: $f$ steigt (oder fällt) auf beiden Seiten.` },
      { l: 2, q: r`$f'$ ist überall positiv. Was folgt für $f$?`, a: [r`$f$ steigt überall und hat keinen Extrempunkt.`, r`$f$ ist überall positiv.`, r`$f$ hat einen Tiefpunkt.`, r`$f$ beschreibt überall eine Linkskurve.`], e: r`Positive Steigung heisst steigender Graph. Über Vorzeichen oder Krümmung von $f$ sagt das nichts.` },
      { l: 2, q: r`Wo $f'$ positiv ist, ist auch $f$ positiv.`, tf: false, e: r`$f'$ beschreibt die Steigung, nicht die Höhe. Ein Graph kann unter der $x$-Achse verlaufen und trotzdem steigen.` },
      { l: 2, q: r`In einem Intervall fällt der Graph von $f'$. Was gilt dort für $f$?`, a: [r`$f$ beschreibt eine Rechtskurve.`, r`$f$ beschreibt eine Linkskurve.`, r`$f$ fällt.`, r`$f$ steigt.`], e: r`Fällt $f'$, so nimmt die Steigung von $f$ ab ($f''<0$): Der Graph krümmt sich nach rechts.` },
      { l: 2, q: r`Zwei Funktionen haben dieselbe Ableitung. Was gilt für ihre Graphen?`, a: [r`Sie sind in $y$-Richtung gegeneinander verschoben (oder gleich).`, r`Sie sind sicher identisch.`, r`Sie sind in $x$-Richtung gegeneinander verschoben.`, r`Sie sind an der $x$-Achse gespiegelt.`], e: r`Die Funktionen unterscheiden sich nur um eine Konstante.` },
      { l: 2, q: r`Der Graph von $f$ ist achsensymmetrisch zur $y$-Achse. Was gilt für den Graphen von $f'$?`, a: [r`Er ist punktsymmetrisch zum Ursprung.`, r`Er ist ebenfalls achsensymmetrisch zur $y$-Achse.`, r`Er hat keine Symmetrie.`, r`Er ist eine waagrechte Gerade.`], e: r`Links der $y$-Achse sind die Steigungen gleich gross wie rechts, aber mit umgekehrtem Vorzeichen.` },
      { l: 2, q: r`$f(x)=\sin x$. Welcher Graph gehört zu $f'$?`, a: [r`$\cos x$`, r`$-\cos x$`, r`$\sin x$`, r`$-\sin x$`], e: r`Bei 0 steigt der Sinus mit Steigung 1, bei $\frac{\pi}{2}$ ist die Tangente waagrecht: Das passt zu $\cos x$.` },
      { l: 2, q: r`$f$ hat bei $x=0$ einen Knick (wie $|x|$). Was zeigt der Graph von $f'$ dort?`, a: [r`Einen Sprung.`, r`Eine Nullstelle.`, r`Einen Hochpunkt.`, r`Ebenfalls einen Knick.`], e: r`Links und rechts vom Knick hat $f$ verschiedene Steigungen; bei 0 selbst ist $f'$ nicht definiert.` },
      { l: 2, q: r`Hat $f'$ bei $x_0$ eine Nullstelle, so hat $f$ dort sicher einen Hoch- oder Tiefpunkt.`, tf: false, e: r`Ohne Vorzeichenwechsel von $f'$ ist es ein Terrassenpunkt, wie bei $f(x)=x^3$ an der Stelle 0.` },

      { l: 3, q: r`Der Graph von $f'$ ist eine nach oben geöffnete Parabel mit den Nullstellen $-1$ und $3$. Was hat $f$?`, a: [r`Einen Hochpunkt bei $-1$ und einen Tiefpunkt bei $3$.`, r`Einen Tiefpunkt bei $-1$ und einen Hochpunkt bei $3$.`, r`Zwei Tiefpunkte.`, r`Wendepunkte bei $-1$ und $3$.`], e: r`Bei $-1$ wechselt $f'$ von plus nach minus, bei $3$ von minus nach plus.` },
      { l: 3, q: r`Der Graph von $f'$ ist eine Parabel mit den Nullstellen $-1$ und $3$. Wo hat $f$ seine Wendestelle?`, a: [r`Bei $x=1$`, r`Bei $x=0$`, r`Bei $x=-1$`, r`Bei $x=3$`], e: r`Die Wendestelle von $f$ ist die Extremstelle von $f'$, also der Scheitel der Parabel in der Mitte zwischen den Nullstellen.` },
      { l: 3, q: r`Auf dem Intervall $[0,2]$ ist $f'(x)=3$, und es ist $f(0)=2$. Wie gross ist $f(2)$?`, a: [r`$8$`, r`$6$`, r`$5$`, r`$3$`], e: r`Mit der konstanten Steigung 3 steigt $f$ auf einer Strecke der Länge 2 um 6.` },
      { l: 3, q: r`Was gibt der orientierte Flächeninhalt zwischen dem Graphen von $f'$ und der $x$-Achse von $a$ bis $b$ an?`, a: [r`Die Änderung $f(b)-f(a)$.`, r`Den Funktionswert $f(b)$.`, r`Die Länge des Graphen von $f$.`, r`Die mittlere Steigung von $f$.`], e: r`Das ist der Hauptsatz: $\int_a^b f'(x)\,dx=f(b)-f(a)$.` },
      { l: 3, q: r`Steigt $f'$ überall streng monoton, so hat $f$ höchstens einen Extrempunkt.`, tf: true, e: r`Eine streng steigende Funktion hat höchstens eine Nullstelle, $f'$ wechselt also höchstens einmal das Vorzeichen.` },
      { l: 3, q: r`Ist $f'$ periodisch, so ist auch $f$ periodisch.`, tf: false, e: r`Gegenbeispiel: $f(x)=x+\sin x$ hat die periodische Ableitung $1+\cos x$, ist selbst aber nicht periodisch.` },
      { l: 3, q: r`Für welche Funktion sind die Graphen von $f$ und $f'$ gleich?`, a: [r`$f(x)=e^x$`, r`$f(x)=x^2$`, r`$f(x)=\sin x$`, r`$f(x)=\ln x$`], e: r`Bei $e^x$ ist an jeder Stelle die Steigung gleich dem Funktionswert.` },
      { l: 3, q: r`$f'$ hat bei $x_0$ einen Hochpunkt, und es ist $f'(x_0)=-1$. Was gilt für $f$ bei $x_0$?`, a: [r`Wendepunkt: $f$ fällt dort, aber weniger steil als in der Umgebung.`, r`Hochpunkt.`, r`Wendepunkt, an dem $f$ am steilsten fällt.`, r`Tiefpunkt.`], e: r`Ein Extremum von $f'$ ist eine Wendestelle von $f$. Der grösste Wert $-1$ ist die «am wenigsten negative» Steigung.` }
    ],

    // ───────────────────────── Ableiten mit Regeln ─────────────────────────
    rg: [
      { l: 1, q: r`Wie lautet die Ableitung von $f(x)=x^5$?`, a: [r`$5x^4$`, r`$x^4$`, r`$5x^5$`, r`$4x^5$`], e: r`Potenzregel: Exponent nach vorne, dann den Exponenten um 1 verkleinern.` },
      { l: 1, q: r`Wie lautet die Ableitung von $f(x)=7$?`, a: [r`$0$`, r`$7$`, r`$1$`, r`$7x$`], e: r`Eine konstante Funktion hat überall die Steigung 0.` },
      { l: 1, q: r`Wie lautet die Ableitung von $f(x)=3x^2$?`, a: [r`$6x$`, r`$3x$`, r`$6x^2$`, r`$5x$`], e: r`Faktorregel: Der Faktor 3 bleibt stehen, $x^2$ wird zu $2x$.` },
      { l: 1, q: r`Wie lautet die Ableitung von $f(x)=x^3+2x$?`, a: [r`$3x^2+2$`, r`$3x^2+2x$`, r`$x^2+2$`, r`$3x^3+2$`], e: r`Summenregel: Jeder Summand wird einzeln abgeleitet.` },
      { l: 1, q: r`Wie heisst die Regel $(u+v)'=u'+v'$?`, a: [r`Summenregel`, r`Produktregel`, r`Kettenregel`, r`Faktorregel`], e: r`Eine Summe wird abgeleitet, indem man die Summanden einzeln ableitet.` },
      { l: 1, q: r`Wie lautet die Ableitung von $f(x)=\sin x$?`, a: [r`$\cos x$`, r`$-\cos x$`, r`$-\sin x$`, r`$\sin x$`], e: r`$(\sin x)'=\cos x$.` },
      { l: 1, q: r`Wie lautet die Ableitung von $f(x)=\cos x$?`, a: [r`$-\sin x$`, r`$\sin x$`, r`$\cos x$`, r`$-\cos x$`], e: r`Der Kosinus fällt bei $x>0$ zunächst, daher das Minus: $(\cos x)'=-\sin x$.` },
      { l: 1, q: r`Wie lautet die Ableitung von $f(x)=e^x$?`, a: [r`$e^x$`, r`$x\,e^{x-1}$`, r`$e^{x-1}$`, r`$\ln x$`], e: r`Die natürliche Exponentialfunktion ist ihre eigene Ableitung. Die Potenzregel gilt nur für $x^n$.` },
      { l: 1, q: r`Wie lautet die Ableitung von $f(x)=\ln x$?`, a: [r`$\frac1x$`, r`$\ln x$`, r`$e^x$`, r`$x$`], e: r`$(\ln x)'=\frac1x$ für $x>0$.` },
      { l: 1, q: r`Es gilt $(u\cdot v)'=u'\cdot v'$.`, tf: false, e: r`Die Produktregel lautet $(u\cdot v)'=u'v+uv'$.` },
      { l: 1, q: r`Wie lautet die Ableitung von $f(x)=\frac1x$?`, a: [r`$-\frac{1}{x^2}$`, r`$\frac{1}{x^2}$`, r`$-\frac1x$`, r`$\ln x$`], e: r`$\frac1x=x^{-1}$, mit der Potenzregel: $-x^{-2}$.` },
      { l: 1, q: r`Wie lautet die Ableitung von $f(x)=\sqrt{x}$?`, a: [r`$\frac{1}{2\sqrt{x}}$`, r`$\frac{1}{\sqrt{x}}$`, r`$2\sqrt{x}$`, r`$\frac{\sqrt{x}}{2}$`], e: r`$\sqrt{x}=x^{1/2}$, mit der Potenzregel: $\frac12x^{-1/2}$.` },

      { l: 2, q: r`Wie lautet die Ableitung von $f(x)=x\cdot e^x$?`, a: [r`$(1+x)\,e^x$`, r`$e^x$`, r`$x\,e^x$`, r`$x^2e^{x-1}$`], e: r`Produktregel: $1\cdot e^x+x\cdot e^x$.` },
      { l: 2, q: r`Wie lautet die Ableitung von $f(x)=(2x+1)^3$?`, a: [r`$6\,(2x+1)^2$`, r`$3\,(2x+1)^2$`, r`$6x^2$`, r`$2\,(2x+1)^3$`], e: r`Kettenregel: äussere Ableitung $3(2x+1)^2$ mal innere Ableitung 2.` },
      { l: 2, q: r`Wie lautet die Ableitung von $f(x)=\sin(3x)$?`, a: [r`$3\cos(3x)$`, r`$\cos(3x)$`, r`$-3\cos(3x)$`, r`$3\sin(3x)$`], e: r`Kettenregel: $\cos(3x)$ mal innere Ableitung 3.` },
      { l: 2, q: r`Wie lautet die Ableitung von $f(x)=\frac{x}{x+1}$?`, a: [r`$\frac{1}{(x+1)^2}$`, r`$\frac{1}{x+1}$`, r`$\frac{2x+1}{(x+1)^2}$`, r`$-\frac{1}{(x+1)^2}$`], e: r`Quotientenregel: $\frac{1\cdot(x+1)-x\cdot1}{(x+1)^2}$.` },
      { l: 2, q: r`Wie lautet die Ableitung von $f(x)=e^{-x^2}$?`, a: [r`$-2x\,e^{-x^2}$`, r`$e^{-x^2}$`, r`$-x^2e^{-x^2-1}$`, r`$-2\,e^{-x^2}$`], e: r`Kettenregel: $e^{-x^2}$ mal innere Ableitung $-2x$.` },
      { l: 2, q: r`Wie lautet die Tangente an $f(x)=x^3$ an der Stelle $x_0=1$?`, a: [r`$y=3x-2$`, r`$y=3x+1$`, r`$y=3x$`, r`$y=x+2$`], e: r`Steigung $f'(1)=3$, Punkt $(1\,|\,1)$: $1=3+q$, also $q=-2$.` },
      { l: 2, q: r`Die Tangente hat die Steigung 2. Welche Steigung hat die Normale im selben Punkt?`, a: [r`$-\frac12$`, r`$\frac12$`, r`$-2$`, r`$2$`], e: r`Senkrechte Geraden: Das Produkt der Steigungen ist $-1$.` },
      { l: 2, q: r`$f(x)=x^2\cdot x^3$ darf man auch ohne Produktregel ableiten: $f(x)=x^5$, also $f'(x)=5x^4$.`, tf: true, e: r`Vereinfachen vor dem Ableiten ist erlaubt und oft der kürzere Weg. Die Produktregel ergibt dasselbe.` },
      { l: 2, q: r`Wie lautet die Ableitung von $f(x)=\ln(x^2)$ für $x>0$?`, a: [r`$\frac2x$`, r`$\frac{1}{x^2}$`, r`$\frac{2}{x^2}$`, r`$2x\ln x$`], e: r`Kettenregel: $\frac{1}{x^2}\cdot2x$. Oder zuerst vereinfachen: $\ln(x^2)=2\ln x$.` },
      { l: 2, q: r`An welcher Stelle hat $f(x)=x^2-4x$ eine waagrechte Tangente?`, a: [r`Bei $x=2$`, r`Bei $x=0$`, r`Bei $x=4$`, r`Bei $x=-2$`], e: r`$f'(x)=2x-4=0$ für $x=2$.` },

      { l: 3, q: r`Wie lautet die Ableitung von $f(x)=x^x$ für $x>0$?`, a: [r`$x^x\,(\ln x+1)$`, r`$x\cdot x^{x-1}$`, r`$x^x\ln x$`, r`$x^x$`], e: r`$x^x=e^{x\ln x}$; Kettenregel und Produktregel: $e^{x\ln x}\cdot(\ln x+1)$.` },
      { l: 3, q: r`Wie lautet die Ableitung von $f(x)=\sin^2x+\cos^2x$?`, a: [r`$0$`, r`$2\sin x\cos x$`, r`$4\sin x\cos x$`, r`$2\sin x+2\cos x$`], e: r`$\sin^2x+\cos^2x=1$ ist konstant. Gerechnet: $2\sin x\cos x-2\cos x\sin x=0$.` },
      { l: 3, q: r`Wie lautet die Ableitung von $f(x)=\frac{\sin x}{x}$?`, a: [r`$\frac{x\cos x-\sin x}{x^2}$`, r`$\frac{\cos x}{x}$`, r`$\frac{\sin x-x\cos x}{x^2}$`, r`$\cos x$`], e: r`Quotientenregel: $\frac{u'v-uv'}{v^2}$ mit $u=\sin x$, $v=x$.` },
      { l: 3, q: r`Wie lautet die Ableitung von $f(x)=\ln(\ln x)$ für $x>1$?`, a: [r`$\frac{1}{x\ln x}$`, r`$\frac{1}{\ln x}$`, r`$\frac{1}{x^2}$`, r`$\frac{\ln x}{x}$`], e: r`Kettenregel: $\frac{1}{\ln x}$ mal innere Ableitung $\frac1x$.` },
      { l: 3, q: r`Für jede Basis $a>0$ gilt $(a^x)'=x\cdot a^{x-1}$.`, tf: false, e: r`Die Potenzregel gilt nur, wenn $x$ in der Basis steht. Richtig ist $(a^x)'=a^x\ln a$.` },
      { l: 3, q: r`Wo schneidet die Tangente an $f(x)=e^x$ im Punkt $(a\,|\,e^a)$ die $x$-Achse?`, a: [r`Bei $x=a-1$`, r`Bei $x=a$`, r`Bei $x=a+1$`, r`Bei $x=0$`], e: r`Tangente: $y=e^a(x-a)+e^a$. Aus $y=0$ folgt $x-a=-1$.` },
      { l: 3, q: r`$f(x)=x^3+x$ ist umkehrbar, und es ist $f(1)=2$. Wie gross ist die Ableitung der Umkehrfunktion an der Stelle 2?`, a: [r`$\frac14$`, r`$4$`, r`$\frac12$`, r`$2$`], e: r`$(f^{-1})'(2)=\frac{1}{f'(1)}$, und $f'(1)=3+1=4$.` },
      { l: 3, q: r`Wie lautet die Ableitung von $f(x)=\sqrt{1+\sqrt{x}}$?`, a: [r`$\frac{1}{4\sqrt{x}\,\sqrt{1+\sqrt{x}}}$`, r`$\frac{1}{2\sqrt{x}\,\sqrt{1+\sqrt{x}}}$`, r`$\frac{1}{2\sqrt{1+\sqrt{x}}}$`, r`$\frac{1}{4\sqrt{x}}$`], e: r`Kettenregel: $\frac{1}{2\sqrt{1+\sqrt{x}}}$ mal innere Ableitung $\frac{1}{2\sqrt{x}}$.` }
    ],

    // ───────────────────────── Kurvendiskussion ─────────────────────────
    kd: [
      { l: 1, q: r`Welche Bedingung muss an einer Extremstelle $x_0$ einer differenzierbaren Funktion erfüllt sein?`, a: [r`$f'(x_0)=0$`, r`$f(x_0)=0$`, r`$f''(x_0)=0$`, r`$f'(x_0)>0$`], e: r`An einem Hoch- oder Tiefpunkt ist die Tangente waagrecht.` },
      { l: 1, q: r`Es ist $f'(x_0)=0$ und $f''(x_0)<0$. Was liegt bei $x_0$ vor?`, a: [r`Ein Hochpunkt.`, r`Ein Tiefpunkt.`, r`Ein Wendepunkt.`, r`Eine Nullstelle.`], e: r`Waagrechte Tangente in einer Rechtskurve: Der Graph liegt links und rechts darunter.` },
      { l: 1, q: r`Ist $f'(x_0)=0$ und $f''(x_0)>0$, so hat $f$ bei $x_0$ einen Tiefpunkt.`, tf: true, e: r`Waagrechte Tangente in einer Linkskurve.` },
      { l: 1, q: r`Wie findet man die Nullstellen von $f$?`, a: [r`Man löst $f(x)=0$.`, r`Man löst $f'(x)=0$.`, r`Man löst $f''(x)=0$.`, r`Man berechnet $f(0)$.`], e: r`Nullstellen sind die Stellen, an denen der Graph die $x$-Achse trifft.` },
      { l: 1, q: r`Welche Bedingung muss an einer Wendestelle $x_0$ erfüllt sein (wenn $f''$ dort existiert)?`, a: [r`$f''(x_0)=0$`, r`$f'(x_0)=0$`, r`$f(x_0)=0$`, r`$f''(x_0)>0$`], e: r`An der Wendestelle wechselt die Krümmung, $f''$ wechselt also das Vorzeichen.` },
      { l: 1, q: r`In einem Intervall ist $f''(x)>0$. Was gilt dort für den Graphen von $f$?`, a: [r`Er beschreibt eine Linkskurve.`, r`Er beschreibt eine Rechtskurve.`, r`Er steigt.`, r`Er fällt.`], e: r`$f''>0$ heisst: Die Steigung nimmt zu, der Graph krümmt sich nach links.` },
      { l: 1, q: r`In einem Intervall ist $f'(x)<0$. Was gilt dort für den Graphen von $f$?`, a: [r`Er fällt.`, r`Er steigt.`, r`Er beschreibt eine Rechtskurve.`, r`Er liegt unter der $x$-Achse.`], e: r`Negative Steigung heisst fallender Graph.` },
      { l: 1, q: r`Wo schneidet der Graph von $f$ die $y$-Achse?`, a: [r`Auf der Höhe $f(0)$.`, r`Auf der Höhe $f'(0)$.`, r`Bei den Lösungen von $f(x)=0$.`, r`Auf der Höhe $f(1)$.`], e: r`Auf der $y$-Achse ist $x=0$.` },
      { l: 1, q: r`Welche Nullstellen hat $f(x)=x^2-4$?`, a: [r`$x=-2$ und $x=2$`, r`nur $x=4$`, r`nur $x=2$`, r`keine`], e: r`$x^2=4$ hat die zwei Lösungen $\pm2$.` },
      { l: 1, q: r`Welchen Tiefpunkt hat $f(x)=x^2-4x$?`, a: [r`$T(2\,|\,-4)$`, r`$T(2\,|\,4)$`, r`$T(4\,|\,0)$`, r`$T(0\,|\,0)$`], e: r`$f'(x)=2x-4=0$ für $x=2$, und $f(2)=4-8=-4$.` },
      { l: 1, q: r`Ein Polynom dritten Grades hat genau einen Wendepunkt.`, tf: true, e: r`$f''$ ist eine Gerade mit Steigung ungleich 0. Sie hat genau eine Nullstelle mit Vorzeichenwechsel.` },
      { l: 1, q: r`Ein Polynom enthält nur gerade Exponenten, z. B. $f(x)=x^4-2x^2+1$. Welche Symmetrie hat der Graph?`, a: [r`Achsensymmetrie zur $y$-Achse.`, r`Punktsymmetrie zum Ursprung.`, r`Keine Symmetrie.`, r`Achsensymmetrie zur $x$-Achse.`], e: r`Dann ist $f(-x)=f(x)$.` },

      { l: 2, q: r`Welche Extrempunkte hat $f(x)=x^3-3x$?`, a: [r`$H(-1\,|\,2)$ und $T(1\,|\,-2)$`, r`$H(1\,|\,2)$ und $T(-1\,|\,-2)$`, r`$H(-1\,|\,-2)$ und $T(1\,|\,2)$`, r`nur $H(0\,|\,0)$`], e: r`$f'(x)=3x^2-3=0$ für $x=\pm1$; $f''(-1)=-6<0$ (Hochpunkt), $f''(1)=6>0$ (Tiefpunkt).` },
      { l: 2, q: r`Bei $f(x)=x^3$ ist $f'(0)=0$. Was liegt bei $x=0$ vor?`, a: [r`Ein Terrassenpunkt (Sattelpunkt).`, r`Ein Hochpunkt.`, r`Ein Tiefpunkt.`, r`Eine Stelle ohne Besonderheit.`], e: r`$f'(x)=3x^2$ wechselt bei 0 das Vorzeichen nicht: Der Graph steigt auf beiden Seiten.` },
      { l: 2, q: r`Bei $f(x)=x^4$ ist $f''(0)=0$. Was liegt bei $x=0$ vor?`, a: [r`Ein Tiefpunkt, kein Wendepunkt: $f''$ wechselt das Vorzeichen nicht.`, r`Ein Wendepunkt.`, r`Ein Terrassenpunkt.`, r`Ein Hochpunkt.`], e: r`$f''(x)=12x^2\ge0$. $f''(x_0)=0$ ist nur notwendig, nicht hinreichend für einen Wendepunkt.` },
      { l: 2, q: r`Zwischen zwei benachbarten Extremstellen eines Polynoms liegt immer eine Wendestelle.`, tf: true, e: r`Zwischen Hoch- und Tiefpunkt muss der Graph von der Rechtskurve in die Linkskurve wechseln (oder umgekehrt).` },
      { l: 2, q: r`Wie verhält sich $f(x)=-2x^3+x$ für $x\to\infty$?`, a: [r`$f(x)\to-\infty$`, r`$f(x)\to+\infty$`, r`$f(x)\to0$`, r`$f(x)\to-2$`], e: r`Für grosse $x$ bestimmt der Summand mit der höchsten Potenz das Verhalten: $-2x^3$.` },
      { l: 2, q: r`Wie viele Extremstellen kann ein Polynom vierten Grades höchstens haben?`, a: [r`3`, r`4`, r`2`, r`1`], e: r`$f'$ hat den Grad 3 und damit höchstens 3 Nullstellen.` },
      { l: 2, q: r`Wo liegt die Wendestelle von $f(x)=x^3-6x^2+9x$?`, a: [r`Bei $x=2$`, r`Bei $x=1$`, r`Bei $x=3$`, r`Bei $x=0$`], e: r`$f''(x)=6x-12=0$ für $x=2$, mit Vorzeichenwechsel.` },
      { l: 2, q: r`Welche Steigung hat die Wendetangente von $f(x)=x^3-6x^2+9x$?`, a: [r`$-3$`, r`$0$`, r`$3$`, r`$-12$`], e: r`$f'(x)=3x^2-12x+9$, an der Wendestelle: $f'(2)=12-24+9=-3$.` },
      { l: 2, q: r`Am Wendepunkt ist die Steigung des Graphen lokal am grössten oder am kleinsten.`, tf: true, e: r`Die Wendestelle ist eine Extremstelle von $f'$.` },
      { l: 2, q: r`Es ist $f'(x)=(x-1)(x+2)$. Wo steigt $f$?`, a: [r`Für $x<-2$ und für $x>1$`, r`Für $-2<x<1$`, r`Nur für $x>1$`, r`Überall`], e: r`Das Produkt ist positiv, wenn beide Faktoren dasselbe Vorzeichen haben.` },

      { l: 3, q: r`Wie viele Extrempunkte hat $f(x)=x^4-4x^3$?`, a: [r`Genau einen (Tiefpunkt bei $x=3$).`, r`Zwei.`, r`Drei.`, r`Keinen.`], e: r`$f'(x)=4x^2(x-3)$. Bei 0 wechselt $f'$ das Vorzeichen nicht (Terrassenpunkt), bei 3 von minus nach plus.` },
      { l: 3, q: r`Für welche $a$ hat $f(x)=x^3+ax$ einen Hoch- und einen Tiefpunkt?`, a: [r`Für $a<0$`, r`Für $a>0$`, r`Nur für $a=0$`, r`Für alle $a$`], e: r`$f'(x)=3x^2+a=0$ hat nur für $a<0$ zwei Lösungen.` },
      { l: 3, q: r`Welchen Hochpunkt hat $f(x)=x\cdot e^{-x}$?`, a: [r`$H\left(1\,\middle|\,\frac1e\right)$`, r`$H(0\,|\,0)$`, r`$H(-1\,|\,-e)$`, r`$H(e\,|\,1)$`], e: r`$f'(x)=(1-x)\,e^{-x}=0$ für $x=1$, und $f(1)=e^{-1}$.` },
      { l: 3, q: r`Wo liegt die Wendestelle von $f(x)=x\cdot e^{-x}$?`, a: [r`Bei $x=2$`, r`Bei $x=1$`, r`Bei $x=0$`, r`Bei $x=e$`], e: r`$f''(x)=(x-2)\,e^{-x}$ wechselt bei 2 das Vorzeichen.` },
      { l: 3, q: r`Hat $f$ bei $x_0$ einen Hochpunkt, so ist $f(x_0)$ der grösste Funktionswert überhaupt.`, tf: false, e: r`Ein Hochpunkt ist nur in seiner Umgebung der höchste Punkt. Weiter weg kann der Graph höher liegen.` },
      { l: 3, q: r`Welche Aussage über $f(x)=x+\frac1x$ stimmt?`, a: [r`Der Hochpunkt $H(-1\,|\,-2)$ liegt tiefer als der Tiefpunkt $T(1\,|\,2)$.`, r`$f$ hat keine Extrempunkte.`, r`$f$ hat bei $x=1$ einen Hochpunkt.`, r`$f$ hat bei $x=0$ einen Extrempunkt.`], e: r`$f'(x)=1-\frac{1}{x^2}=0$ für $x=\pm1$. Die Polstelle bei 0 trennt die beiden Äste.` },
      { l: 3, q: r`Ein Polynom dritten Grades hat die Extremstellen $x_1$ und $x_2$. Wo liegt die Wendestelle?`, a: [r`Bei $\frac{x_1+x_2}{2}$`, r`Bei $x_1$`, r`Das lässt sich nicht allgemein sagen.`, r`Bei $x=0$`], e: r`$f'$ ist eine Parabel mit den Nullstellen $x_1$ und $x_2$; ihr Scheitel liegt in der Mitte.` },
      { l: 3, q: r`Es ist $f'(x_0)=0$, $f''(x_0)=0$ und $f'''(x_0)\neq0$. Was liegt bei $x_0$ vor?`, a: [r`Ein Terrassenpunkt (Wendepunkt mit waagrechter Tangente).`, r`Ein Hochpunkt.`, r`Ein Tiefpunkt.`, r`Darüber lässt sich nichts sagen.`], e: r`$f''(x_0)=0$ mit $f'''(x_0)\neq0$ ergibt eine Wendestelle; dazu kommt die waagrechte Tangente.` }
    ],

    // ───────────────────────── Extremwertprobleme ─────────────────────────
    ext: [
      { l: 1, q: r`Was ist die Zielfunktion eines Extremwertproblems?`, a: [r`Die Grösse, die möglichst gross oder klein werden soll, als Funktion einer Variablen.`, r`Die Gleichung, die die Variablen verknüpft.`, r`Die Ableitung der gesuchten Grösse.`, r`Der Bereich der erlaubten Werte.`], e: r`Zum Beispiel die Fläche $A(x)$ oder die Oberfläche $O(x)$.` },
      { l: 1, q: r`Wozu dient die Nebenbedingung?`, a: [r`Um eine Variable durch die andere auszudrücken.`, r`Um die Ableitung zu berechnen.`, r`Um das Ergebnis zu prüfen.`, r`Um den Definitionsbereich zu vergrössern.`], e: r`So enthält die Zielfunktion am Schluss nur noch eine Variable.` },
      { l: 1, q: r`Ein Rechteck mit den Seiten $x$ und $y$ hat den Umfang 20. Was folgt daraus?`, a: [r`$y=10-x$`, r`$y=20-x$`, r`$y=20-2x$`, r`$y=10-2x$`], e: r`$2x+2y=20$, also $x+y=10$.` },
      { l: 1, q: r`Wie lautet die Zielfunktion für die Fläche dieses Rechtecks (Umfang 20)?`, a: [r`$A(x)=x\,(10-x)$`, r`$A(x)=x\,(20-x)$`, r`$A(x)=2x+2\,(10-x)$`, r`$A(x)=x^2$`], e: r`Fläche = Länge mal Breite, mit $y=10-x$.` },
      { l: 1, q: r`Welcher Definitionsbereich ist für $A(x)=x\,(10-x)$ sinnvoll?`, a: [r`$0<x<10$`, r`$x>0$`, r`Alle reellen Zahlen.`, r`$0<x<20$`], e: r`Beide Seiten $x$ und $10-x$ müssen positiv sein.` },
      { l: 1, q: r`Für welches $x$ ist $A'(x)=10-2x$ gleich null?`, a: [r`$x=5$`, r`$x=10$`, r`$x=2$`, r`$x=0$`], e: r`$10-2x=0$ ergibt $x=5$.` },
      { l: 1, q: r`Welches Rechteck mit dem Umfang 20 hat die grösste Fläche?`, a: [r`Das Quadrat mit der Seitenlänge 5.`, r`Das Rechteck mit den Seiten 4 und 6.`, r`Das Rechteck mit den Seiten 2 und 8.`, r`Das Rechteck mit den Seiten 1 und 9.`], e: r`$A(5)=25$; die anderen haben die Flächen 24, 16 und 9.` },
      { l: 1, q: r`Liegt das Optimum im Innern des Definitionsbereichs, so ist dort die Tangente an die Zielfunktion waagrecht.`, tf: true, e: r`Deshalb setzt man die Ableitung der Zielfunktion gleich null.` },
      { l: 1, q: r`Wie prüft man, ob bei $x_0$ wirklich ein Maximum der Zielfunktion $A$ vorliegt?`, a: [r`$A''(x_0)<0$ (oder $A'$ wechselt von plus nach minus).`, r`$A(x_0)>0$`, r`$A'(x_0)>0$`, r`$x_0>0$`], e: r`$A'(x_0)=0$ allein unterscheidet nicht zwischen Maximum, Minimum und Terrassenpunkt.` },
      { l: 1, q: r`Mit 40 m Zaun wird an einer Mauer eine rechteckige Weide eingezäunt; die Mauer bildet eine Seite. $x$ ist die Seite senkrecht zur Mauer, $y$ die Seite parallel dazu. Wie lautet die Nebenbedingung?`, a: [r`$2x+y=40$`, r`$2x+2y=40$`, r`$x+y=40$`, r`$x\cdot y=40$`], e: r`Der Zaun wird nur für drei Seiten gebraucht: zweimal $x$ und einmal $y$.` },
      { l: 1, q: r`Für welches $x$ wird $A(x)=x\,(40-2x)$ am grössten?`, a: [r`$x=10$`, r`$x=20$`, r`$x=\frac{40}{3}$`, r`$x=5$`], e: r`$A'(x)=40-4x=0$ für $x=10$.` },
      { l: 1, q: r`Bei einem Extremwertproblem soll die Zielfunktion immer möglichst gross werden.`, tf: false, e: r`Oft ist das Kleinste gesucht, zum Beispiel der geringste Materialverbrauch bei einer Dose.` },

      { l: 2, q: r`Wie gross wird die Weide an der Mauer (40 m Zaun) höchstens?`, a: [r`$200\ \text{m}^2$`, r`$100\ \text{m}^2$`, r`$400\ \text{m}^2$`, r`$150\ \text{m}^2$`], e: r`Für $x=10$ ist $y=40-20=20$, also $A=10\cdot20$.` },
      { l: 2, q: r`Aus einem Karton von 30 cm mal 20 cm werden an den Ecken Quadrate der Seite $x$ ausgeschnitten; die Ränder werden hochgeklappt. Welcher Definitionsbereich gilt für $V(x)=x\,(30-2x)(20-2x)$?`, a: [r`$0<x<10$`, r`$0<x<15$`, r`$0<x<20$`, r`$x>0$`], e: r`Auch die kürzere Seite $20-2x$ muss positiv bleiben.` },
      { l: 2, q: r`Warum muss man den Definitionsbereich der Zielfunktion beachten?`, a: [r`Lösungen von $Z'(x)=0$ können ausserhalb liegen, und das Optimum kann am Rand liegen.`, r`Weil die Ableitung sonst nicht berechnet werden kann.`, r`Weil die Zielfunktion ausserhalb nicht differenzierbar ist.`, r`Er ist nur für die Zeichnung wichtig.`], e: r`Rechnerisch gefundene Stellen müssen zur Situation passen.` },
      { l: 2, q: r`Bei der Schachtel aus dem 30-mal-20-Karton hat $V'(x)=0$ die Lösungen $x\approx3.92$ und $x\approx12.74$. Welche gilt?`, a: [r`$x\approx3.92$, denn $12.74$ liegt nicht im Definitionsbereich.`, r`$x\approx12.74$, weil dieser Wert grösser ist.`, r`Beide.`, r`Keine von beiden.`], e: r`Für $x>10$ wäre die Seite $20-2x$ negativ.` },
      { l: 2, q: r`Hat $Z'(x)=0$ im Definitionsbereich $[a,b]$ keine Lösung, so nimmt $Z$ den grössten Wert am Rand an, also bei $a$ oder $b$.`, tf: true, e: r`Ohne waagrechte Tangente im Innern steigt oder fällt $Z$ auf dem ganzen Intervall.` },
      { l: 2, q: r`Eine zylinderförmige Dose mit Radius $r$ und Höhe $h$ soll $1000\ \text{cm}^3$ fassen. Wie lautet die Nebenbedingung?`, a: [r`$\pi r^2h=1000$`, r`$2\pi rh=1000$`, r`$\pi r^2+h=1000$`, r`$2\pi r^2+2\pi rh=1000$`], e: r`Volumen des Zylinders: Grundfläche mal Höhe.` },
      { l: 2, q: r`Die Oberfläche der Dose ist $O(r)=2\pi r^2+\frac{2000}{r}$. Was geschieht für $r\to0$?`, a: [r`$O$ wächst über alle Grenzen.`, r`$O$ geht gegen 0.`, r`$O$ geht gegen 1000.`, r`$O$ geht gegen 2000.`], e: r`Eine sehr dünne Dose muss sehr hoch sein; ihr Mantel $\frac{2000}{r}$ wird riesig.` },
      { l: 2, q: r`Unter der Parabel $y=9-x^2$ liegt ein Rechteck auf der $x$-Achse, symmetrisch zur $y$-Achse, mit der rechten oberen Ecke bei $x$. Wie lautet die Fläche?`, a: [r`$A(x)=2x\,(9-x^2)$`, r`$A(x)=x\,(9-x^2)$`, r`$A(x)=18x$`, r`$A(x)=(9-x^2)^2$`], e: r`Breite $2x$ (von $-x$ bis $x$), Höhe $9-x^2$.` },
      { l: 2, q: r`Für welches $x$ wird $A(x)=2x\,(9-x^2)$ am grössten ($0<x<3$)?`, a: [r`$x=\sqrt{3}$`, r`$x=3$`, r`$x=1.5$`, r`$x=\sqrt{6}$`], e: r`$A(x)=18x-2x^3$, $A'(x)=18-6x^2=0$ für $x^2=3$.` },
      { l: 2, q: r`Unter allen Rechtecken mit gleicher Fläche hat das Quadrat den kleinsten Umfang.`, tf: true, e: r`Mit $y=\frac{A}{x}$ ist $U(x)=2x+\frac{2A}{x}$; aus $U'(x)=0$ folgt $x^2=A$, also $x=y$.` },

      { l: 3, q: r`Welche Form hat die geschlossene Dose mit festem Volumen und kleinster Oberfläche?`, a: [r`Höhe = Durchmesser ($h=2r$)`, r`Höhe = Radius ($h=r$)`, r`$h=\pi r$`, r`$h=4r$`], e: r`$O'(r)=4\pi r-\frac{2V}{r^2}=0$ ergibt $V=2\pi r^3$; mit $V=\pi r^2h$ folgt $h=2r$.` },
      { l: 3, q: r`Welche Punkte der Parabel $y=x^2$ liegen dem Punkt $(0\,|\,1)$ am nächsten?`, a: [r`Die Punkte mit $x=\pm\frac{1}{\sqrt2}$`, r`Der Punkt mit $x=0$`, r`Die Punkte mit $x=\pm1$`, r`Die Punkte mit $x=\pm\frac12$`], e: r`$d^2=x^2+(x^2-1)^2=x^4-x^2+1$; die Ableitung $4x^3-2x$ ist null für $x=0$ (dort $d^2=1$) und $x^2=\frac12$ (dort $d^2=\frac34$).` },
      { l: 3, q: r`Warum darf man statt des Abstands $d$ auch $d^2$ minimieren?`, a: [r`Weil $d\ge0$ ist und Quadrieren für solche Zahlen die Reihenfolge erhält: Beide sind an derselben Stelle am kleinsten.`, r`Weil $d$ und $d^2$ gleich gross sind.`, r`Weil $d^2$ dieselbe Ableitung hat wie $d$.`, r`Das ist nur eine Näherung.`], e: r`So spart man sich die Wurzel beim Ableiten.` },
      { l: 3, q: r`Zwei positive Zahlen haben die Summe 10. Wann ist die Summe ihrer Quadrate am kleinsten?`, a: [r`Wenn beide Zahlen 5 sind.`, r`Bei 1 und 9.`, r`Je verschiedener die Zahlen, desto kleiner.`, r`Sie ist immer gleich gross.`], e: r`$S(x)=x^2+(10-x)^2$, $S'(x)=4x-20=0$ für $x=5$; $S(5)=50$.` },
      { l: 3, q: r`Für $x,y\ge0$ mit $x+y=10$ wird $x^2+y^2$ am Rand, also für $x=0$ oder $x=10$, am grössten.`, tf: true, e: r`Im Innern liegt nur das Minimum ($x=5$). Der grösste Wert 100 wird am Rand angenommen, wo die Ableitung nicht null ist.` },
      { l: 3, q: r`Aus einem quadratischen Karton der Seitenlänge $a$ werden an den Ecken Quadrate der Seite $x$ ausgeschnitten. Für welches $x$ wird das Volumen der Schachtel am grössten?`, a: [r`$x=\frac{a}{6}$`, r`$x=\frac{a}{4}$`, r`$x=\frac{a}{3}$`, r`$x=\frac{a}{2}$`], e: r`$V(x)=x\,(a-2x)^2$, $V'(x)=(a-2x)(a-6x)$. Bei $x=\frac a2$ ist das Volumen null.` },
      { l: 3, q: r`Eine oben offene Dose (ohne Deckel) soll bei festem Volumen möglichst wenig Blech brauchen. Welche Form hat sie?`, a: [r`Höhe = Radius ($h=r$)`, r`Höhe = Durchmesser ($h=2r$)`, r`$h=\frac{r}{2}$`, r`$h=\pi r$`], e: r`$O(r)=\pi r^2+\frac{2V}{r}$, $O'(r)=0$ ergibt $V=\pi r^3$, also $h=r$. Ohne Deckel wird die Dose flacher.` },
      { l: 3, q: r`Multipliziert man die Zielfunktion mit einer positiven Konstanten, so ändert sich die Extremstelle nicht.`, tf: true, e: r`Aus $Z'(x)=0$ wird $c\cdot Z'(x)=0$ mit denselben Lösungen. Nur der Extremwert ändert sich.` }
    ],

    // ───────────────────────── Polynom aus Bedingungen ─────────────────────────
    stb: [
      { l: 1, q: r`Wie viele Koeffizienten hat ein Polynom dritten Grades $f(x)=ax^3+bx^2+cx+d$?`, a: [r`4`, r`3`, r`2`, r`5`], e: r`$a$, $b$, $c$ und $d$.` },
      { l: 1, q: r`Wie viele Bedingungen braucht man, um ein Polynom vom Grad $n$ eindeutig festzulegen?`, a: [r`$n+1$`, r`$n$`, r`$n-1$`, r`$2n$`], e: r`So viele wie Koeffizienten: von $x^n$ bis zur Konstanten sind es $n+1$.` },
      { l: 1, q: r`«Der Graph geht durch $P(1\,|\,2)$.» Welche Gleichung folgt daraus?`, a: [r`$f(1)=2$`, r`$f(2)=1$`, r`$f'(1)=2$`, r`$f'(2)=1$`], e: r`Der Punkt liegt auf dem Graphen: Zum $x$-Wert 1 gehört der $y$-Wert 2.` },
      { l: 1, q: r`«Der Graph hat bei $x=2$ die Steigung 3.» Welche Gleichung folgt daraus?`, a: [r`$f'(2)=3$`, r`$f(2)=3$`, r`$f'(3)=2$`, r`$f''(2)=3$`], e: r`Die Steigung ist der Wert der ersten Ableitung.` },
      { l: 1, q: r`«Der Graph hat bei $x=1$ eine Extremstelle.» Welche Gleichung folgt daraus?`, a: [r`$f'(1)=0$`, r`$f(1)=0$`, r`$f''(1)=0$`, r`$f'(0)=1$`], e: r`An einer Extremstelle ist die Tangente waagrecht.` },
      { l: 1, q: r`«Der Graph hat bei $x=0$ eine Wendestelle.» Welche Gleichung folgt daraus?`, a: [r`$f''(0)=0$`, r`$f'(0)=0$`, r`$f(0)=0$`, r`$f'''(0)=0$`], e: r`An einer Wendestelle ist die zweite Ableitung null.` },
      { l: 1, q: r`Wie viele Gleichungen liefert die Angabe «Hochpunkt $H(2\,|\,5)$»?`, a: [r`Zwei: $f(2)=5$ und $f'(2)=0$.`, r`Eine: $f(2)=5$.`, r`Drei.`, r`Keine.`], e: r`Der Punkt liegt auf dem Graphen, und die Tangente ist dort waagrecht.` },
      { l: 1, q: r`Geht der Graph von $f(x)=ax^3+bx^2+cx+d$ durch den Ursprung, so ist $d=0$.`, tf: true, e: r`$f(0)=d$ muss 0 sein.` },
      { l: 1, q: r`Wie lautet die Ableitung des Ansatzes $f(x)=ax^3+bx^2+cx+d$?`, a: [r`$f'(x)=3ax^2+2bx+c$`, r`$f'(x)=ax^2+bx+c$`, r`$f'(x)=3ax^2+2bx+c+d$`, r`$f'(x)=3x^2+2x$`], e: r`Die Koeffizienten bleiben als Faktoren stehen, die Konstante $d$ fällt weg.` },
      { l: 1, q: r`Welche Gerade geht durch $(0\,|\,1)$ und $(2\,|\,5)$?`, a: [r`$y=2x+1$`, r`$y=2x$`, r`$y=x+1$`, r`$y=5x+1$`], e: r`$f(0)=1$ gibt $q=1$; $f(2)=2m+1=5$ gibt $m=2$.` },
      { l: 1, q: r`«Der Graph schneidet die $y$-Achse auf der Höhe 3.» Welche Gleichung folgt daraus?`, a: [r`$f(0)=3$`, r`$f(3)=0$`, r`$f'(0)=3$`, r`$f(3)=3$`], e: r`Auf der $y$-Achse ist $x=0$.` },
      { l: 1, q: r`Ein Punkt, durch den der Graph geht, liefert genau eine Gleichung.`, tf: true, e: r`Nämlich $f(x_P)=y_P$.` },

      { l: 2, q: r`Welche Gleichungen liefert die Angabe «Wendepunkt $W(1\,|\,2)$»?`, a: [r`$f(1)=2$ und $f''(1)=0$`, r`$f(1)=2$ und $f'(1)=0$`, r`nur $f''(1)=0$`, r`$f'(1)=0$ und $f''(1)=0$`], e: r`Der Punkt liegt auf dem Graphen, und die zweite Ableitung ist dort null. Die Steigung ist nicht festgelegt.` },
      { l: 2, q: r`«Der Graph berührt die $x$-Achse bei $x=3$.» Welche Gleichungen folgen daraus?`, a: [r`$f(3)=0$ und $f'(3)=0$`, r`nur $f(3)=0$`, r`$f'(3)=0$ und $f''(3)=0$`, r`$f(0)=3$`], e: r`Berühren heisst: gemeinsamer Punkt und gleiche Steigung wie die $x$-Achse, also 0.` },
      { l: 2, q: r`Gesucht ist ein Polynom vierten Grades, dessen Graph achsensymmetrisch zur $y$-Achse ist. Welcher Ansatz passt?`, a: [r`$f(x)=ax^4+bx^2+c$`, r`$f(x)=ax^4+bx^3+cx^2+dx+e$`, r`$f(x)=ax^4+bx^3$`, r`$f(x)=ax^3+bx$`], e: r`Bei Achsensymmetrie kommen nur gerade Exponenten vor. Das spart zwei Unbekannte.` },
      { l: 2, q: r`Gesucht ist ein Polynom dritten Grades, dessen Graph punktsymmetrisch zum Ursprung ist. Welcher Ansatz passt?`, a: [r`$f(x)=ax^3+bx$`, r`$f(x)=ax^3+bx^2$`, r`$f(x)=ax^3+b$`, r`$f(x)=ax^2+bx$`], e: r`Bei Punktsymmetrie zum Ursprung kommen nur ungerade Exponenten vor.` },
      { l: 2, q: r`Eine Parabel hat den Scheitel $S(1\,|\,2)$ und geht durch $P(0\,|\,3)$. Wie lautet ihre Gleichung?`, a: [r`$f(x)=x^2-2x+3$`, r`$f(x)=x^2+2x+3$`, r`$f(x)=x^2+3$`, r`$f(x)=2x^2-4x+3$`], e: r`Ansatz $a(x-1)^2+2$; aus $f(0)=a+2=3$ folgt $a=1$.` },
      { l: 2, q: r`Die Angabe «Terrassenpunkt (Sattelpunkt) bei $x=1$» liefert die zwei Gleichungen $f'(1)=0$ und $f''(1)=0$.`, tf: true, e: r`Waagrechte Tangente und Wendestelle zugleich.` },
      { l: 2, q: r`Die Tangente im Punkt $P(1\,|\,2)$ hat die Gleichung $y=3x-1$. Welche Gleichungen folgen daraus?`, a: [r`$f(1)=2$ und $f'(1)=3$`, r`$f(1)=3$ und $f'(1)=-1$`, r`$f(1)=2$ und $f'(1)=-1$`, r`$f(3)=1$ und $f'(1)=2$`], e: r`Der Graph geht durch $P$ und hat dort die Steigung der Tangente.` },
      { l: 2, q: r`Welches Polynom zweiten Grades erfüllt $f(0)=1$, $f(1)=0$ und $f(2)=3$?`, a: [r`$f(x)=2x^2-3x+1$`, r`$f(x)=x^2-2x+1$`, r`$f(x)=2x^2-x+1$`, r`$f(x)=-2x^2+3x+1$`], e: r`$c=1$; $a+b=-1$ und $4a+2b=2$ ergeben $a=2$, $b=-3$.` },
      { l: 2, q: r`Erfüllt das gefundene Polynom $f'(2)=0$, so hat es bei $x=2$ sicher den verlangten Hochpunkt.`, tf: false, e: r`$f'(2)=0$ ist nur notwendig. Es könnte auch ein Tiefpunkt oder Terrassenpunkt sein, deshalb am Schluss nachprüfen.` },
      { l: 2, q: r`Es sind mehr Bedingungen gegeben, als der Ansatz Koeffizienten hat. Was kann geschehen?`, a: [r`Das Gleichungssystem kann unlösbar sein: Kein Polynom dieses Grades erfüllt alles.`, r`Es gibt immer unendlich viele Lösungen.`, r`Es gibt immer genau eine Lösung.`, r`Der Grad des Polynoms wird automatisch kleiner.`], e: r`Zu viele Bedingungen passen nur zusammen, wenn sie sich nicht widersprechen.` },

      { l: 3, q: r`Der Graph eines Polynoms dritten Grades ist punktsymmetrisch zum Ursprung und hat den Hochpunkt $H(1\,|\,2)$. Wie lautet es?`, a: [r`$f(x)=-x^3+3x$`, r`$f(x)=x^3-3x$`, r`$f(x)=-x^3+3x^2$`, r`$f(x)=-2x^3+4x$`], e: r`Ansatz $ax^3+bx$: $a+b=2$ und $3a+b=0$ ergeben $a=-1$, $b=3$. Probe: $f''(1)=-6<0$.` },
      { l: 3, q: r`Ein Polynom dritten Grades hat im Ursprung einen Terrassenpunkt und geht durch $P(1\,|\,2)$. Wie lautet es?`, a: [r`$f(x)=2x^3$`, r`$f(x)=2x^2$`, r`$f(x)=x^3+x$`, r`$f(x)=2x^3+x$`], e: r`$f(0)=0$, $f'(0)=0$ und $f''(0)=0$ ergeben $d=c=b=0$; aus $f(1)=2$ folgt $a=2$.` },
      { l: 3, q: r`Wie viele Unbekannte erspart die Angabe «achsensymmetrisch zur $y$-Achse» bei einem Polynom vierten Grades?`, a: [r`Zwei (die Koeffizienten von $x^3$ und $x$ sind null).`, r`Eine.`, r`Drei.`, r`Keine.`], e: r`Statt fünf Koeffizienten bleiben in $ax^4+bx^2+c$ noch drei.` },
      { l: 3, q: r`Zwei Kurvenstücke sollen bei $x=1$ ohne Sprung und ohne Knick ineinander übergehen. Was muss dort übereinstimmen?`, a: [r`Funktionswert und erste Ableitung.`, r`Nur der Funktionswert.`, r`Nur die erste Ableitung.`, r`Nur die zweite Ableitung.`], e: r`Gleicher Funktionswert: kein Sprung. Gleiche Steigung: kein Knick.` },
      { l: 3, q: r`Durch drei Punkte mit verschiedenen $x$-Werten geht immer genau eine Parabel $y=ax^2+bx+c$ mit $a\neq0$.`, tf: false, e: r`Liegen die drei Punkte auf einer Geraden, so ergibt sich $a=0$, also keine Parabel.` },
      { l: 3, q: r`Der Graph eines Polynoms vierten Grades ist achsensymmetrisch zur $y$-Achse, geht durch $(0\,|\,1)$ und berührt die $x$-Achse bei $x=1$. Wie lautet es?`, a: [r`$f(x)=x^4-2x^2+1$`, r`$f(x)=x^4-2x^2$`, r`$f(x)=-x^4+2x^2+1$`, r`$f(x)=x^4+2x^2+1$`], e: r`Ansatz $ax^4+bx^2+c$: $c=1$, $a+b+1=0$ und $4a+2b=0$ ergeben $a=1$, $b=-2$. Es ist $f(x)=(x^2-1)^2$.` },
      { l: 3, q: r`«Der Graph hat bei $x=2$ einen Wendepunkt mit der Wendetangente $y=-3x+7$.» Wie viele Gleichungen liefert das?`, a: [r`Drei: $f(2)=1$, $f'(2)=-3$ und $f''(2)=0$.`, r`Zwei: $f'(2)=-3$ und $f''(2)=0$.`, r`Eine: $f''(2)=0$.`, r`Vier.`], e: r`Der Wendepunkt liegt auf der Tangente: $y=-3\cdot2+7=1$.` },
      { l: 3, q: r`Zu vier Bedingungen gibt es immer genau ein Polynom dritten Grades.`, tf: false, e: r`Bedingungen können sich widersprechen oder voneinander abhängen. Dann gibt es keine oder unendlich viele Lösungen.` }
    ]
  };
})();
